import"./main-HbDxD-dm.js";import"./cta-block-C-BhtqFY.js";import{r as s,b as c}from"./accordion-hjQ2x1Nh.js";import"./format-CBHhwPyh.js";const l=[{id:"what-we-make",question:"Що ви виробляєте і чим відрізняються ваші два бренди?",answer:'У Ясногородці на Київщині працюють два бренди під одним дахом. <a href="/catalog.html?brand=Bazylsprings">Bazylsprings</a> — віскі повного циклу. <a href="/catalog.html?brand=YasnoCraft">YasnoCraft</a> — джин, кальвадос, фруктові шнапси, настоянки та колекційна «Фрукт у пляшці». Про те, як усе влаштовано, розповідаємо на сторінці <a href="/about.html#about-brands">«Про дім»</a>.'},{id:"visit-production",question:"Чи можна побачити виробництво вживу?",answer:'Так, за попереднім записом: екскурсія дистилерією, від мідних кубів до складу з бочками. Залиште заявку на екскурсію в <a href="/contacts.html#excursion">формі запису</a>, а години, тривалість і розмір групи ми узгодимо індивідуально.'},{id:"tasting",question:"Чи можна спробувати напої перед покупкою?",answer:'Дегустація проходить під час візиту в нашій дегустаційній у Ясногородці: лише для повнолітніх, 18+. Запишіться на візит через <a href="/contacts.html#excursion">форму запису</a>, і ми підкажемо, що саме можна спробувати. Дізнатися більше про візит можна <a href="/about.html#about-visit">тут</a>.'},{id:"pickup",question:"Чи можна забрати замовлення самовивозом?",answer:"Так, самовивіз доступний із дегустаційної в Ясногородці Київської області. Спосіб доставки ви обираєте під час оформлення замовлення. Точну адресу й години роботи ми повідомляємо після оформлення."},{id:"volumes",question:"Які об'єми пляшок у вас є?",answer:`Більшість напоїв випускаємо у двох об'ємах, 0,5 і 0,7 л, кожен зі своєю ціною: наприклад, джин «Ясний» коштує 850 ₴ за 0,5 л і 1 150 ₴ за 0,7 л. Окремі позиції мають один об'єм: White Whiskey розливаємо у 0,5 л, «Фрукт у пляшці» — у 0,7 л. Об'єм обирають прямо на картці товару в <a href="/catalog.html">каталозі</a>.`},{id:"whisky",question:"Коли з'явиться витримане віскі Bazylsprings?",answer:'Витримані релізи плануємо пізніше, тож категорія «Віскі» в каталозі позначена як «скоро». Уже зараз можна замовити невитриманий <a href="/product.html?slug=whiskey-white">White Whiskey</a> (0,5 л, 45%, 1 690 ₴), який отримав перше місце на Ukrainian Craft Spirits Awards. Щоб не пропустити новий реліз, залиште пошту в <a href="#subscribe-email">реліз-листі внизу сторінки</a>.'},{id:"fruit-in-bottle",question:"Що таке «Фрукт у пляшці» і чому там лише кавун?",answer:`Кавун дозріває всередині пляшки, і лише потім її заливають чистим дистилятом. Це колекційна позиція обмеженим тиражем: 0,7 л, 40%, 3 200 ₴. Поки що в лінійці одна така пляшка, <a href="/product.html?slug=fruit-watermelon">Фрукт у пляшці · Кавун</a>, нові позиції з'являтимуться разом із сезонними релізами.`},{id:"gift-sets",question:"Як вибрати подарунок і чи є готові набори?",answer:'Є готові подарункові набори для різних приводів, а також можливість зібрати свій: напої, упаковка й листівка. Усе зібрано на сторінці <a href="/gifts.html">«Подарунок та набори»</a>. Під час оформлення замовлення оберіть «Це подарунок»: додамо листівку з вашим текстом, подарункову упаковку й приберемо ціни з вкладення.'},{id:"corporate",question:"Чи робите корпоративні подарунки та гравіювання?",answer:'Так: набори для партнерів і команди від 10 штук, із гравіюванням. Вартість залежить від складу набору й тиражу, тому розраховуємо її індивідуально. Напишіть нам через <a href="/contacts.html#corporate">форму зі зверненням «Корпоративні»</a>, вкажіть кількість і привід.'},{id:"horeca",question:"Чи співпрацюєте з барами та ресторанами?",answer:'Так. Розкажіть про заклад і потреби, і ми обговоримо асортимент та умови співпраці. Подайте заявку в <a href="/contacts.html#horeca">формі «Опт / HoReCa»</a>, відповімо протягом робочого дня.'},{id:"delivery",question:"Куди й як швидко ви доставляєте?",answer:"По всій Україні: Новою Поштою у відділення або поштомат. У Києві доступний також кур'єр. Строк залежить від способу доставки та міста, його видно на етапі оформлення замовлення, до оплати. Статус і трекінг надішлемо на пошту після відправлення."},{id:"payment",question:"Які способи оплати доступні?",answer:"Оплата карткою, Apple Pay та Google Pay, а також накладений платіж. Доступні способи ви побачите на кроці оплати. Перед оплатою потрібно підтвердити вік (див. питання про 18+)."},{id:"age",question:"Як підтверджується вік 18+?",answer:"Спершу сайт запитує про повноліття на вході. Перед оплатою вік підтверджується через Дію, а при отриманні замовлення його перевіряють ще раз. Без підтвердження ми не можемо передати напій."},{id:"storage",question:"Як зберігати пляшку і чи псується відкритий напій?",answer:'Зберігайте пляшку щільно закритою, у темному місці без різких перепадів температури, подалі від прямого сонця. Міцні напої не скисають, але з часом змінюють аромат, тому відкриту пляшку краще не тримати надто довго. Особливості конкретного напою описані на його <a href="/catalog.html">картці в каталозі</a>.'},{id:"returns",question:"Чи можна повернути або обміняти напій?",answer:'Умови повернення й обміну прописані в публічній оферті. Якщо пляшка прибула пошкодженою, напишіть нам одразу після отримання, розберемося індивідуально. Зверніться через <a href="/contacts.html">контакти</a>, додайте номер замовлення й фото.'}],d=new Set(["A","BR","P"]),h=/^(\/(?!\/)|#|https?:\/\/|mailto:|tel:)/i;function o(r,t){r.childNodes.forEach(e=>{if(e.nodeType===3)return t.append(document.createTextNode(e.textContent));if(e.nodeType!==1)return;if(!d.has(e.tagName))return o(e,t);const a=document.createElement(e.tagName.toLowerCase());if(e.tagName==="A"){const i=(e.getAttribute("href")||"").trim();h.test(i)&&(a.setAttribute("href",i),/^https?:/i.test(i)&&(a.target="_blank",a.rel="noopener"))}e.tagName!=="BR"&&o(e,a),t.append(a)})}function u(r){const t=new DOMParser().parseFromString(`<body>${r}</body>`,"text/html").body,e=document.createElement("div");if(o(t,e),!e.querySelector("p")){const a=document.createElement("p");a.append(...e.childNodes),e.append(a)}return e.innerHTML}const n=document.getElementById("faq-list");if(n){const r=document.getElementById("faq-title");n.innerHTML=s(l.map(e=>({title:e.question,html:u(e.answer)})),{label:"Питання й відповіді",variant:"cards",cols:3,open:0,lead:1});const t=n.querySelector("[data-lead]");t&&r&&t.prepend(r),c(n)}
